// Fork of "3D Torus-Knot Vibe-Field" by Chimel. https://shadertoy.com/view/X33BRl
// 2025-01-21 20:27:27

#ifdef GL_ES
precision mediump float;
#endif

/*****************************************************
 * 1) ROTATION HELPERS (vec3, float)
 *****************************************************/
vec3 rotateXVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
        p.x,
        c*p.y - s*p.z,
        s*p.y + c*p.z
    );
}

vec3 rotateYVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
         c*p.x + s*p.z,
         p.y,
        -s*p.x + c*p.z
    );
}

vec3 rotateZVec(vec3 p, float a)
{
    float c = cos(a), s = sin(a);
    return vec3(
        c*p.x - s*p.y,
        s*p.x + c*p.y,
        p.z
    );
}

/*****************************************************
 * 2) GLOBAL CONSTANTS & SETTINGS
 *****************************************************/
#define PI      3.14159265359
#define TWO_PI  6.28318530718

// Double wires (like a braided cord)
#define WIRES_PER_KNOT   2

// Number of line segments per wire
#define N_SAMPLES        60

// Wire thickness
#define WIRE_RADIUS      0.08

// We match the second program's scale = 1.0
#define SCENE_SCALE      1.0

// Spiral spin speed
#define ROT_SPEED        8.0

// The “figure‐8 arcs” twist factor from the second code
float twistArcs = 10.0;

/*****************************************************
 * 3) FIGURE‐8 (arcs) KNOT from second code
 *    Param t in [0..4], NOT closed
 *****************************************************/
// arcsRawPos: returns a point in 3D for t in [0..4].
vec3 arcsRawPos(float t)
{
    float T = mod(t, 4.0);
    float I = floor(T);
    float sf = fract(T);
    float angle;
    vec3 p = vec3(0.0);

    if(I < 0.5)
    {
        // front arc => [0..1]
        angle = -PI*0.5 + PI*sf;
        p = vec3(0.25*cos(angle), 0.25*sin(angle), 0.25);
    }
    else if(I < 1.5)
    {
        // top arc => [1..2], flipped
        angle = -PI + PI*sf;
        p = vec3(-0.25*cos(angle), 0.25, 0.25*sin(angle));
        // pivot around Y
        p = rotateYVec(p, PI*0.5);
    }
    else if(I < 2.5)
    {
        // back arc => [2..3]
        angle = -PI*0.5 + PI*sf;
        p = vec3(0.25*cos(angle), 0.25*sin(angle), -0.25);
    }
    else
    {
        // bottom arc => [3..4], flipped
        angle = -PI + PI*sf;
        p = vec3(-0.25*cos(angle), -0.25, 0.25*sin(angle));
        p = rotateYVec(p, PI*0.5);
    }

    return p;
}

// Approx. tangent using forward/back difference
vec3 arcsRawTangent(float t)
{
    float eps = 0.0001;
    vec3 fwd = arcsRawPos(t + eps);
    vec3 bwd = arcsRawPos(t - eps);
    return normalize(fwd - bwd);
}

/*****************************************************
 * 4) EXTRA SNIPPET TRANSFORM & FINAL ROTATIONS
 *****************************************************/
// The snippet transform from your second code
vec3 transformArcs(vec3 p)
{
    p = rotateZVec(p, PI/3.2);
    p = rotateYVec(p, PI/4.2);
    p = rotateXVec(p, PI/1.2);
    return p;
}
vec3 transformArcsTangent(vec3 t)
{
    t = rotateZVec(t, PI/3.2);
    t = rotateYVec(t, PI/4.2);
    t = rotateXVec(t, PI/1.2);
    return t;
}

// Additional “manual 45°” style rotations from the second code:
const float arcsRotX = 55.0 * PI / 180.0;
const float arcsRotY = 5.0  * PI / 180.0;
const float arcsRotZ = 65.0 * PI / 180.0;

/*****************************************************
 * 5) FRENET‐LIKE FRAME FOR FIGURE‐8
 *****************************************************/
struct FrameData {
    vec3 pos;
    vec3 tangent;
    vec3 normal;
    vec3 binormal;
};

FrameData getArcsFrame(float t)
{
    FrameData f;
    // raw arcs
    vec3 rp = arcsRawPos(t);
    vec3 rt = arcsRawTangent(t);

    // snippet transforms
    rp = transformArcs(rp);
    rt = transformArcsTangent(rt);

    // final manual rotations
    rp = rotateXVec(rp, arcsRotX);
    rp = rotateYVec(rp, arcsRotY);
    rp = rotateZVec(rp, arcsRotZ);

    rt = rotateXVec(rt, arcsRotX);
    rt = rotateYVec(rt, arcsRotY);
    rt = rotateZVec(rt, arcsRotZ);

    // scale (SCENE_SCALE = 1.0 to match second code)
    rp *= SCENE_SCALE;

    // compute normal/binormal
    vec3 up = vec3(0,1,0);
    vec3 n  = normalize(cross(rt, up));
    if(length(n) < 0.00001) {
        up = vec3(1,0,0);
        n  = normalize(cross(rt, up));
    }
    vec3 b = cross(rt, n);

    f.pos      = rp;
    f.tangent  = rt;
    f.normal   = n;
    f.binormal = b;
    return f;
}

/*****************************************************
 * 6) DOUBLE‐WIRE SPIRAL OFFSET
 *****************************************************/
vec3 getArcsWireCenterPos(int wireId, float t, float time)
{
    FrameData fd = getArcsFrame(t);

    // param t in [0..4], so normalize it into [0..1]
    float u = t / 4.0;

    // wire #1 => phase=0, wire #2 => phase=π
    float phaseShift = (wireId == 0) ? 0.0 : PI;

    // Combined twist angle
    float twistAngle = ROT_SPEED*time
                     + twistArcs*(u*TWO_PI)
                     + phaseShift;

    // radius of the wire offset
    float radius = 0.03 * SCENE_SCALE;
    vec3 offset = radius * (
        cos(twistAngle)*fd.normal +
        sin(twistAngle)*fd.binormal
    );
    return fd.pos + offset;
}

/*****************************************************
 * 7) CAMERA
 *****************************************************/
struct Camera {
    vec3 ro;
    vec3 forward;
    vec3 right;
    vec3 up;
};

Camera getCamera(float time, vec2 mouse, vec2 resolution)
{
    // Start at (0,0,4)
    vec3 baseCam = vec3(0.0, 0.0, 4.0);
    vec3 ro = baseCam;

    bool userClicking = (iMouse.z > 0.5);

    if(!userClicking)
    {
        // auto spin around Y
        float spin = 0.001 * time;
        ro = rotateYVec(ro, spin);
    }
    else
    {
        // manual rotation with mouse
        float yaw   = (mouse.x / resolution.x)*2.0*PI - PI;
        float pitch = (mouse.y / resolution.y)*1.0*PI - 0.5*PI;
        ro = rotateYVec(ro, yaw);
        ro = rotateXVec(ro, pitch);
    }

    vec3 fw = normalize(-ro);
    vec3 rt = normalize(cross(fw, vec3(0,1,0)));
    vec3 up = cross(rt, fw);

    Camera c;
    c.ro      = ro;
    c.forward = fw;
    c.right   = rt;
    c.up      = up;
    return c;
}

vec3 projectToScreen(vec3 p3D, Camera cam)
{
    float focal = 3.5;

    vec3 diff = p3D - cam.ro;
    float cx  = dot(diff, cam.right);
    float cy  = dot(diff, cam.up);
    float cz  = dot(diff, cam.forward);

    // near or behind the camera => clip
    if(cz < 0.001) {
        return vec3(9999.0,9999.0,9999.0);
    }

    float ndcX = focal * cx / cz;
    float ndcY = focal * cy / cz;
    return vec3(ndcX, ndcY, cz);
}

/*****************************************************
 * 8) DISTANCE FROM PIXEL TO LINE SEGMENT (2D)
 *****************************************************/
float distToSegment2D(vec2 P, vec2 A, vec2 B)
{
    vec2 v  = B - A;
    vec2 w  = P - A;
    float c1 = dot(w,v);
    if(c1 <= 0.0) {
        return length(P - A);
    }
    float c2 = dot(v,v);
    if(c2 <= c1) {
        return length(P - B);
    }
    float b = c1 / c2;
    vec2 Pb = A + b*v;
    return length(P - Pb);
}

/*****************************************************
 * 9) SIMPLE HASH & NOISE (for SMOKE)
 *****************************************************/
float hash12(vec2 p)
{
    const float K = 2.49999999;
    return fract(sin(dot(p, vec2(37.1,61.7))) * 43758.5453 + K);
}

float noise2D(vec2 p)
{
    vec2 i = floor(p);
    vec2 f = fract(p);

    float a = hash12(i + vec2(0,0));
    float b = hash12(i + vec2(1,0));
    float c = hash12(i + vec2(0,1));
    float d = hash12(i + vec2(1,1));

    vec2 u = f*f*(3.0 - 2.0*f);
    return mix( mix(a,b,u.x), mix(c,d,u.x), u.y );
}

float fbm(vec2 p)
{
    float f = 0.1;
    float s = 0.80;
    for(int i=0; i<5; i++)
    {
        f += noise2D(p)*s;
        p *= 2.02;
        s *= 0.5;
    }
    return f;
}

/*****************************************************
 * 10) MIN DIST TO THE 8-KNOT (SCREEN SPACE)
 *****************************************************/
float getMinDistToArcs(vec2 uv, float time, Camera cam)
{
    float minD = 9999.0;

    // arcs param range = [0..4], NOT closed
    float tMax = 4.0;

    for(int wireId=0; wireId<WIRES_PER_KNOT; wireId++)
    {
        for(int i=0; i<N_SAMPLES; i++)
        {
            float t0 = float(i)*(tMax/float(N_SAMPLES));
            float t1 = float(i+1)*(tMax/float(N_SAMPLES));

            // don't connect last -> first
            if(i == (N_SAMPLES-1)) {
                break;
            }
            // skip bridging sub-arcs
            if(floor(t0) != floor(t1)) {
                continue;
            }

            vec3 p0_3D = getArcsWireCenterPos(wireId, t0, time);
            vec3 p1_3D = getArcsWireCenterPos(wireId, t1, time);

            vec3 p0_clip = projectToScreen(p0_3D, cam);
            vec3 p1_clip = projectToScreen(p1_3D, cam);

            if(p0_clip.z>9000.0 && p1_clip.z>9000.0) {
                continue;
            }

            float dLine = distToSegment2D(uv, p0_clip.xy, p1_clip.xy);
            minD = min(minD, dLine);
        }
    }
    return minD;
}

/*****************************************************
 * 11) SMOKE FIELD
 *****************************************************/
vec3 getSmokeColor(vec2 uv, float time, float minDistToKnot)
{
    // upward scrolling
    vec2 p = uv;
    float speedUp = 0.6;
    p.y += time * speedUp;

    // gentle horizontal sway
    float swayFreq = 0.50;
    float swayAmp  = 0.01;
    p.x += swayAmp * sin(p.y*swayFreq + time);

    // swirl near knot
    float swirlStrength = 0.3;
    float swirlFactor = clamp(1.0 - minDistToKnot/0.4, 0.0, 1.0);
    float angle = swirlStrength * swirlFactor;
    float ca = cos(angle), sa = sin(angle);
    vec2 dp = p - uv;
    vec2 rp = vec2(
        dp.x*ca - dp.y*sa,
        dp.x*sa + dp.y*ca
    );
    p = uv + rp;

    // fractal noise
    float n = fbm(p * 2.0);

    // blue smoke
    vec3 smokeDark  = vec3(0.000,0.000,0.000);
    vec3 smokeLight = vec3(0.000,0.251,1.000);
    vec3 baseSmoke  = mix(smokeDark, smokeLight, n);

    // fade out near top
    float fadeTop = clamp(10.5 - uv.y*1.5, 0.0, 1.0);
    return baseSmoke * fadeTop;
}

/*****************************************************
 * 12) MAIN
 *****************************************************/
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized coords
    vec2 uv = (2.0*fragCoord - iResolution.xy)/iResolution.y;

    // camera
    Camera cam = getCamera(iTime, iMouse.xy, iResolution.xy);

    //---------------------------------------------
    // 1) Distance to figure-8 arcs
    //---------------------------------------------
    float minD = getMinDistToArcs(uv, iTime, cam);

    //---------------------------------------------
    // 2) Smoke & background
    //---------------------------------------------
    vec3 smokeCol = getSmokeColor(uv, iTime, minD);

    float grad = 0.5 * (uv.y + 1.0);
    grad = clamp(grad, 0.0, 1.0);
    vec3 colTop    = vec3(0.5); 
    vec3 colBottom = vec3(0.5);
    vec3 bgGrad    = mix(colBottom, colTop, grad);

    // Blend smoke
    float smokeAlpha = 0.8; 
    vec3 bgColor = mix(bgGrad, smokeCol, smokeAlpha);

    //---------------------------------------------
    // 3) VIBRATIONAL RINGS AROUND THE KNOT
    //---------------------------------------------
    float frequency = 30.0; // more => tighter rings
    float speed     = 15.0; // ring animation speed
    float wave      = sin(minD * frequency - iTime * speed);

    // wave in [-1..1], shift to [0..1]
    float vibr = 2.5 + 2.5*wave;

    // sharpen lines
    vibr = smoothstep(0.45, 0.55, vibr);

    // ring color & strength
    vec3 ringColor  = vec3(0.000,0.122,0.400); // bright blue
    float intensity = 0.4;

    vec3 vibColor = mix(bgColor, ringColor, vibr * intensity);

    //---------------------------------------------
    // 4) Draw the figure‐8 wires in front
    //---------------------------------------------
    float closestZ   = 99999.0;
    vec3  finalColor = vibColor;

    float tMax = 4.0; // arcs param range
    for(int wireId=0; wireId<WIRES_PER_KNOT; wireId++)
    {
        for(int i=0; i<N_SAMPLES; i++)
        {
            float t0 = float(i)*(tMax/float(N_SAMPLES));
            float t1 = float(i+1)*(tMax/float(N_SAMPLES));

            // no wrap since arcs are open
            if(i == (N_SAMPLES-1)) {
                break;
            }
            // skip bridging different arcs
            if(floor(t0) != floor(t1)) {
                continue;
            }

            vec3 p0_3D = getArcsWireCenterPos(wireId, t0, iTime);
            vec3 p1_3D = getArcsWireCenterPos(wireId, t1, iTime);

            vec3 p0_clip = projectToScreen(p0_3D, cam);
            vec3 p1_clip = projectToScreen(p1_3D, cam);

            if(p0_clip.z>9000.0 && p1_clip.z>9000.0) {
                continue;
            }

            float dist2Line = distToSegment2D(uv, p0_clip.xy, p1_clip.xy);
            if(dist2Line < WIRE_RADIUS)
            {
                float segZ = min(p0_clip.z, p1_clip.z);
                if(segZ < closestZ)
                {
                    closestZ = segZ;

                    // wire #1 => black, wire #2 => white
                    vec3 baseColor = (wireId == 0)
                                     ? vec3(0.0,0.0,0.0)
                                     : vec3(1.0,1.0,1.0);

                    // fade from 0.9..1.0 near center line
                    float f = 1.0 - clamp(dist2Line / WIRE_RADIUS, 0.0, 1.0);
                    float shade = 0.9 + 0.1*f;
                    vec3 wireColor = baseColor * shade;

                    // distance-based softening
                    wireColor /= (0.9 + 0.03 * segZ);

                    finalColor = wireColor;
                }
            }
        }
    }

    fragColor = vec4(finalColor, 1.0);
}
